styles:
.b-showcase-fonts {
    padding-block: var(--site-space-6);
}

.b-showcase-fonts__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-fonts__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-fonts__scripts {
    display: grid;
    gap: var(--site-space-3);
    margin: 0 0 var(--site-space-5);
}

.b-showcase-fonts__row {
    display: grid;
    gap: var(--site-space-1);
    padding: var(--site-space-3) var(--site-space-4);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}

.b-showcase-fonts__row.is-fallback {
    border-style: dashed;
}

.b-showcase-fonts__script {
    color: var(--site-color-text-muted);
    font-size: 0.875em;
}

.b-showcase-fonts__lang {
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.b-showcase-fonts__sample {
    margin: 0;
    font-size: var(--site-font-size-4);
    overflow-wrap: anywhere;
}

.b-showcase-fonts__caption {
    margin: 0;
    color: var(--site-color-text-muted);
    font-size: 0.875em;
}

.b-showcase-fonts__weights {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-2) var(--site-space-5);
    margin-top: var(--site-space-2);
    font-size: var(--site-font-size-4);
}

.b-showcase-fonts__number {
    color: var(--site-color-text-muted);
    font-size: 0.75em;
    font-variant-numeric: tabular-nums;
}

.b-showcase-fonts__weight--300 { font-weight: 300; }
.b-showcase-fonts__weight--400 { font-weight: 400; }
.b-showcase-fonts__weight--500 { font-weight: 500; }
.b-showcase-fonts__weight--600 { font-weight: 600; }
.b-showcase-fonts__weight--700 { font-weight: 700; }
.b-showcase-fonts__weight--800 { font-weight: 800; }

.b-showcase-fonts__weight--italic {
    font-style: italic;
}
